## Section1(not reported)
## Problem1(4.1.5.24)
## Author()
## Institution()
## Language(en-US)

DOCUMENT();

#############
# Load Macros
#############

loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "PGlateximage.pl",
  "PCCmacros.pl",
  "PGchoicemacros.pl",
  "contextForm.pl",
  "contextFraction.pl",
  "parserGraphTool.pl",
  "ORCCA.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');

#######
# Setup
#######

do {
  ($x,$y) = (-8..8)[NchooseK(17,2)];
  @h = (-9..$x-1,$x+1..9)[NchooseK(18,2)];
  @k = (-9..$y-1,$y+1..9)[NchooseK(18,2)];
  Context("Fraction");
  Context()->noreduce('(-x)+y', '(-x)-y');
  @m = map{Fraction(($y - $k[$_])/($x - $h[$_]))} (0,1);
} until ($m[0] != 1 && $m[1] != 1 && abs(atan2($m[0],1) - atan2($m[1],1)) > 0.2);
@n = map{($_->value)[0]} (@m);
@d = map{($_->value)[1]} (@m);
@f = map{Formula("$m[$_] (x - $h[$_]) + $k[$_]")->reduce} (0,1);

@low = map{(-10 - $k[$_])/$m[$_] + $h[$_]} (0,1);
@high = map{(10 - $k[$_])/$m[$_] + $h[$_]} (0,1);
@dom0 = num_sort(-10, 10, $low[0], $high[0]);
($l[0], $r[0]) = (@dom0)[1,2];
@dom1 = num_sort(-10, 10, $low[1], $high[1]);
($l[1], $r[1]) = (@dom1)[1,2];

$gt = GraphTool(
  "{line, solid, ($h[0], $k[0]), ($h[0] + $d[0], $k[0] + $n[0])}",
  "{line, solid, ($h[1], $k[1]), ($h[1] + $d[1], $k[1] + $n[1])}",
)->with(
  availableTools => [ "LineTool" ],
  showInStatic => 0,
  cmpOptions => {
    list_checker => sub {
      my ($correct, $student, $ans, $value) = @_;
      return 0 if $ans->{isPreview};
      my $score = 0; my @errors; my $count = 1;
      my ($p1x, $p1y) = $correct->[0]->extract(3)->value;
      my ($p2x, $p2y) = $correct->[0]->extract(4)->value;
      my ($p3x, $p3y) = $correct->[1]->extract(3)->value;
      my ($p4x, $p4y) = $correct->[1]->extract(4)->value;
      my @stdform = (
        $p1y - $p2y, $p2x - $p1x, $p1x * $p2y - $p2x * $p1y,
        $p3y - $p4y, $p4x - $p3x, $p3x * $p4y - $p4x * $p3y
      );
      my $pointOnLine = sub {
        my ($a, $b, $c, $point) = @_;  my ($x, $y) = $point->value;
        return $a * $x + $b * $y + $c == 0;
      };
      my @line = (0, 0);
      for (@$student) {
        my $nth = Value::List->NameForNumber($count++);
        if ($pointOnLine->(@stdform[0..2],$_->extract(3)) && $pointOnLine->(@stdform[0..2],$_->extract(4))) {
          $line[0] = 1; $score += 1; next
        }
        if ($pointOnLine->(@stdform[3..5],$_->extract(3)) && $pointOnLine->(@stdform[3..5],$_->extract(4))) {
          $line[1] = 1; $score += 1; next
        }
        push(@errors, "The $nth line graphed is incorrect.");
      }
      return (($line[0] && $line[1]) ? $score : 0, @errors);
    }
  }
);
Context("Point");
Context()->strings->remove("NONE");
Context()->strings->add(
  "no solutions" => {},
);
for (
  "no solution",
  "none",
  "there are no solutions",
  "the solution set is empty",
  "solution set is empty",
  "empty set",
  "∅",
  "{}",
  "{ }",
  "{  }",
  "{   }"
) {
  Context()->strings->add($_ => {alias => "no solutions"});
}
Context()->strings->add(
  "infinitely many solutions" => {},
);
for (
  "infinitely many",
  "infinite solution set",
  "infinite",
  "the solution set is infinite",
  "solution set is infinite"
) {
  Context()->strings->add($_ => {alias => "infinitely many solutions"});
}
$solution = Point($x,$y)->cmp(
  mathQuillOpts => 'disabled'
);

$image_1 = createLaTeXImage();
$image_1->addToPreamble(latexImagePreamble());
$image_1->BEGIN_LATEX_IMAGE
\begin{tikzpicture}
  \begin{axis}[
      xmin=-10,
      xmax=10,
      ymin=-10,
      ymax=10,
      xtick = {-10,-5,5,10},
      minor xtick = {-10,...,10},
      ytick = {-10,-5,5,10},
      minor ytick = {-10,...,10},
      width=0.47\orccaprintwidth,
    ]
    \addplot+[domain=$l[0]:$r[0]]{$f[0]};
    \addplot+[domain=$l[1]:$r[1]]{$f[1]};
  \end{axis}
\end{tikzpicture}

END_LATEX_IMAGE

#############################
# Exercise Group Introduction
#############################

BEGIN_PGML
Solve the given system of linear equations graphically.

END_PGML

######
# Body
######

BEGIN_PGML
[`
                  \left\{
                    \begin{alignedat}{3}
                      y \amp= [$f[0]]\\
                      y \amp= [$f[1]]
                    \end{alignedat}
                  \right.
                `]

[_]{$gt}{1}

[@KeyboardInstructions('Enter the solution here. If there are no solutions, enter [|no solutions|]*. If there are infinitely many solutions, enter [|infinitely many solutions|]*.')@]**

[_]{$solution}{16}

END_PGML

##########
# Solution
##########

BEGIN_PGML_SOLUTION
If we graph these lines, we find they cross.

>> [@image(insertGraph($image_1), width=>282, alt=>qq"a coordinate plot of two lines that cross at ($x, $y)")@]*  <<

The only solution is where they cross, which is at [`[$solution->{rh_ans}{correct_ans}]\text{.}`]

END_PGML_SOLUTION

#############
# End Problem
#############

ENDDOCUMENT();
